installation.script:
#!/bin/bash
# Installation Script pour Node.js NeoHeberg

echo "🚀 Début de l'installation Node.js pour NeoHeberg..."

mkdir -p /mnt/server
cd /mnt/server

echo "📁 Création de la structure de base..."

# Création d'un package.json de base si inexistant
if [ ! -f package.json ]; then
    echo "📦 Création d'un package.json de base..."
    cat > package.json << 'EOF'
{
  "name": "neoheberg-nodejs-app",
  "version": "1.0.0",
  "description": "Application Node.js pour NeoHeberg",
  "main": "index.js",
  "scripts": {
    "start": "node index.js"
  },
  "dependencies": {},
  "engines": {
    "node": ">=12.0.0"
  }
}
EOF
fi

# Création d'un index.js de base si inexistant
if [ ! -f index.js ]; then
    echo "📄 Création d'un index.js de base..."
    cat > index.js << 'EOF'
const http = require('http');
const port = process.env.PORT || 3000;

const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(`
    <div style="font-family: Arial, sans-serif; text-align: center; padding: 50px;">
      <h1>🚀 Serveur Node.js NeoHeberg</h1>
      <p>✅ Votre application fonctionne correctement !</p>
      <p><strong>Version Node.js:</strong> ${process.version}</p>
      <p><strong>Port:</strong> ${port}</p>
      <p style="color: #666; margin-top: 30px;">Modifiez le fichier index.js pour personnaliser votre application</p>
    </div>
  `);
});

server.listen(port, '0.0.0.0', () => {
  console.log(`✅ Serveur NeoHeberg démarré sur le port ${port}`);
  console.log(`🌐 Application accessible sur http://0.0.0.0:${port}`);
});

process.on('SIGTERM', () => {
  console.log('🛑 Arrêt du serveur...');
  server.close(() => {
    console.log('✅ Serveur arrêté proprement');
    process.exit(0);
  });
});
EOF
fi

echo "✅ Installation terminée pour NeoHeberg !"
echo "📋 Fichiers créés:"
ls -la
echo ""
echo "ℹ️  Les dépendances npm seront automatiquement installées à chaque démarrage du serveur."
